import unittest
from candidate import digitSum

class TestDigitSum(unittest.TestCase):
    def test_empty_string_returns_zero(self):
        self.assertEqual(digitSum(""), 0)

    def test_no_uppercase_returns_zero(self):
        self.assertEqual(digitSum("abcxyz"), 0)

    def test_all_uppercase_sums_correctly(self):
        self.assertEqual(digitSum("ABC"), 198)
        self.assertEqual(digitSum("XYZ"), 240+88+90)

    def test_mixed_characters_sums_only_uppercase(self):
        self.assertEqual(digitSum("abAB"), 131)
        self.assertEqual(digitSum("abcCd"), 67)
        self.assertEqual(digitSum("helloE"), 69)
        self.assertEqual(digitSum("woArBld"), 131)
        self.assertEqual(digitSum("aAaaaXa"), 153)

    def test_numeric_and_punctuation_ignored(self):
        self.assertEqual(digitSum("A1B!"), 131)
        self.assertEqual(digitSum("A,B.C"), 131)

    def test_unicode_uppercase_letters_sum(self):
        self.assertEqual(digitSum("ÄÖÜ"), 196 + 214 + 220)

    def test_string_with_newlines_and_tabs_ignored(self):
        self.assertEqual(digitSum("A\nB\tC"), 65 + 66 + 67)

    def test_long_string_uppercase_sum(self):
        long_a = "A" * 1000
        self.assertEqual(digitSum(long_a), 65 * 1000)

    def test_non_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            digitSum(123)
        with self.assertRaises(TypeError):
            digitSum(None)
        with self.assertRaises(TypeError):
            digitSum(12.34)

    def test_bytes_input_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            digitSum(b"ABC")

    def test_consistency_same_input_same_output(self):
        s = "TestCaseABC"
        first = digitSum(s)
        second = digitSum(s)
        self.assertEqual(first, second)

    def test_single_uppercase_character(self):
        self.assertEqual(digitSum("Z"), 90)

    def test_single_lowercase_character(self):
        self.assertEqual(digitSum("z"), 0)

    def test_string_with_only_punctuation(self):
        self.assertEqual(digitSum("!@#"), 0)

    def test_string_with_mixed_unicode(self):
        self.assertEqual(digitSum("aΩAΩ"), ord('A') + ord('Ω'))

if __name__ == "__main__":
    unittest.main()
